package state

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"testing"
)

// Expected hashes are the independent Step50 original-byte operand model,
// not values generated by FreezeEnemyRules. All5banks x4quality x4environment.
func TestOriginalEnemyTransformBanks(t *testing.T) {
	var data struct {
		Banks map[string]string
		Cases []struct {
			Source      string `json:"source_bank_sha256"`
			Quality     uint16 `json:"AD13_signed_index"`
			Environment uint16 `json:"A249_and_3"`
			Result      string `json:"result_sha256"`
		}
	}
	if err := json.Unmarshal([]byte(originalEnemyOperands), &data); err != nil {
		t.Fatal(err)
	}
	if len(data.Banks) != 5 || len(data.Cases) != 80 {
		t.Fatal("independent source denominator")
	}
	for _, c := range data.Cases {
		b, err := hex.DecodeString(data.Banks[c.Source])
		if err != nil || len(b) != 128 {
			t.Fatal(err)
		}
		var raw [16][8]byte
		for i := range raw {
			copy(raw[i][:], b[8*i:8*i+8])
		}
		switches := c.Quality | c.Environment<<8
		r, err := FreezeEnemyRules("source-bank", raw, switches, false)
		if err != nil {
			t.Fatal(err)
		}
		var out []byte
		for _, row := range r.Definitions {
			out = append(out, row[:]...)
		}
		if got := fmt.Sprintf("%x", sha256.Sum256(out)); got != c.Result {
			t.Fatalf("quality%d env%d: %s != %s", c.Quality, c.Environment, got, c.Result)
		}
		if err = r.Validate("source-bank", switches); err != nil {
			t.Fatal(err)
		}
		if raw != r.Raw {
			t.Fatal("raw bank mutated")
		}
		r.Definitions[4][4] ^= 1
		if r.Validate("source-bank", switches) == nil {
			t.Fatal("changed frozen row admitted")
		}
	}
}
func TestEnemyTransformWrapAndFrozenSettings(t *testing.T) {
	var raw [16][8]byte
	for i := range raw {
		raw[i] = [8]byte{byte(i), 2, 250, 250, 5, 6, 7, 8}
	}
	r, err := FreezeEnemyRules("GULF5", raw, 0x300, true)
	if err != nil {
		t.Fatal(err)
	}
	if !r.Disabled || r.Definitions[0][2] != 84 || r.Definitions[0][3] != 33 {
		t.Fatal("byte wrapping", r)
	}
	if r.Validate("GULF4", 0x300) == nil || r.Validate("GULF5", 0x301) == nil {
		t.Fatal("settings/world not frozen")
	}
	var absent *EnemyRules
	if absent.Validate("GULF5", 0) == nil {
		t.Fatal("nil definitions admitted")
	}
}

